def run(scene, robot):
    moved = scene.with_role("moved")
    spoon = moved[0] if moved else scene.of_kind("spoon")[0]
    tub = scene.containers()[0]
    for c in scene.containers():
        if c.kind == "tub":
            tub = c
            break
    if scene.is_inside(scene.get(spoon.name), scene.get(tub.name)):
        return
    robot.pick(scene.get(spoon.name))
    robot.place_in(scene.get(tub.name))
